if hashlib.sha256(payload).hexdigest() != "0555f39fc337da276d3f37cf70bbfe6d26367fbd02c467cfa8e28684b8d8b2e9":
    raise SystemExit('Embedded source checksum failed; obtain an intact script.')
with zipfile.ZipFile(io.BytesIO(payload)) as archive:
    # Verify the complete payload before changing a destination file.
    for name in archive.namelist():
        rel=PurePosixPath(name)
        if rel.is_absolute() or '..' in rel.parts:
            raise SystemExit('Invalid embedded filename: '+name)
        target=root.joinpath(*rel.parts)
        if not target.resolve().is_relative_to(root):
            raise SystemExit('Code destination leaves Project through a symlink: '+name)
        if name.endswith('.py'):ast.parse(archive.read(name),filename=name)
    written=0
    for name in archive.namelist():
        target=root/name
        if name=='tests.py' and target.exists() and target.stat().st_size > 0:
            print('Preserved existing supplied tests.py')
            continue
        target.parent.mkdir(parents=True,exist_ok=True)
        fd,temp=tempfile.mkstemp(prefix='.clearauth-write-',dir=target.parent)
        try:
            with os.fdopen(fd,'wb') as stream:stream.write(archive.read(name))
            os.chmod(temp,0o644)
            os.replace(temp,target)
        finally:
            if os.path.exists(temp):os.unlink(temp)
        written+=1
    print('Wrote',written,'implementation/configuration/documentation files to',root)
if not (root/'.env').exists():
    with (root/'.env').open('x') as stream:
        stream.write('GEMINI_API_KEY=\nGEMINI_MODEL=gemini-2.5-flash\n')
    print('Created .env template; set credentials only when you choose to use live Gemini.')
else:
    print('Preserved existing .env')
PY_BOOTSTRAP
if [[ "$WRITE_ONLY" == 1 ]]; then
  printf '%s\n' 'Source installation complete. No dependencies installed and no data or database changed.'
  exit 0
fi
"$PYTHON_BIN" - <<'PY_PREFLIGHT'
from pathlib import Path
required=[
 'data/authorisation_history_train.csv','data/authorisation_history_eval.csv',
 'data/surgical_stays_train.csv','data/surgical_stays_eval.csv',
 'data/clinical_note_sentences.csv','data/input/open_requests.csv',
 'data/input/request_notes.csv',
]
missing=[p for p in required if not Path(p).is_file()]
if not Path('data/docs').is_dir() or len(list(Path('data/docs').glob('*.[pP][dD][fF]')))!=16:
    missing.append('data/docs/ (expected all sixteen supplied PDFs)')
if missing:raise SystemExit('Missing supplied inputs:\n  '+'\n  '.join(missing))
PY_PREFLIGHT
if [[ ! -x .venv/bin/python ]]; then
  "$PYTHON_BIN" -m venv .venv
fi
PY=.venv/bin/python
"$PY" -c 'import sys; assert sys.version_info >= (3,12), "Remove or rename the incompatible .venv, then rerun with Python 3.12+"'
printf '\n%s\n' '[1/6] Installing the validated dependency versions'
"$PY" -m pip install -r requirements-lock.txt
printf '\n%s\n' '[2/6] Creating database tables and seed accounts (existing records retained)'
"$PY" run_database_setup.py
printf '\n%s\n' '[3/6] Cleaning the five raw extracts and writing the quality report'
"$PY" run_data_pipeline.py
printf '\n%s\n' '[4/6] Training and evaluating the three models'
"$PY" run_model_training.py
printf '\n%s\n' '[5/6] Building the policy knowledge index (embedding download may be needed)'
"$PY" run_knowledge_indexing.py
if [[ "$SKIP_TESTS" == 0 ]]; then
  printf '\n%s\n' '[6/6] Running supplied tests with only the external Gemini boundary mocked'
  # Offline verification uses isolated records and never calls Gemini.
  HF_HUB_OFFLINE=1 "$PY" verify.py --offline
  HF_HUB_OFFLINE=1 "$PY" local_workflow_smoke.py
else
  printf '\n%s\n' '[6/6] Tests skipped by --skip-tests'
fi
printf '\n%s\n' 'ClearAuth AI build complete.' 'Start API in this terminal:' '  .venv/bin/python run_api_service.py' 'Start dashboard in a second terminal, from Project:' '  .venv/bin/python -m streamlit run run_dashboard.py' 'Dashboard: http://localhost:8080  API docs: http://localhost:8081/docs' 'Live Gemini remains untested. Configure .env before starting live reviews or chat.'
